// build.rs — Proto compilation build script
//
// Cargo runs this BEFORE compiling any src/ files.
//
// What it does:
//   Reads  → ../proto/connector/v1/connector.proto and ../proto/shield/v1/shield.proto
//   Calls  → protoc (system protobuf compiler) via tonic-prost-build
//   Writes → target/build/<hash>/out/connector.rs  (auto-generated Rust structs + gRPC client)
//
// The generated code contains:
//   - EnrollRequest, EnrollResponse       (used by enrollment.rs in Phase 5)
//   - HeartbeatRequest, HeartbeatResponse  (used by heartbeat.rs in Phase 6)
//   - ConnectorServiceClient              (gRPC client for both RPCs)
//
// main.rs pulls the generated code in via:  tonic::include_proto!("connector")
//
// Rebuild trigger:
//   cargo:rerun-if-changed ensures this script re-runs only when the proto file changes.
//   Unrelated source changes do NOT trigger a proto recompile.
//
// IMPORTANT: The copied proto must stay byte-for-byte compatible with the
// controller's proto definition.

// ── Connector-revocation timing (decided 2026-10-21, design D13–D15) ──────
// Baked into the binary at build time; NOT read from connector.conf at
// runtime. Precedence: build environment variable > connector/.env >
// the accepted default. Out-of-range values fail the build. H = 15 s
// (control_stream::AUTHORIZATION_FRESHNESS) is fixed by design D1.
const H_MS: u64 = 15_000;
const MIN_RESPONSE_BUDGET_MS: u64 = 1_000;

/// (env key, default, min, max)
const AUTHZ_TIMING: [(&str, u64, u64, u64); 5] = [
    ("AUTHZ_REQUEST_PERIOD_MS", 4_500, 500, H_MS - MIN_RESPONSE_BUDGET_MS), // P
    ("CONTROL_RECONNECT_BASE_MS", 1_000, 100, 60_000),                      // O5
    ("CONTROL_RECONNECT_MAX_MS", 5_000, 100, 60_000),                       // O5
    ("CONTROL_RECONNECT_JITTER_PCT", 20, 0, 50),                             // O5
    ("DISABLED_SHIELD_CLOSE_SECS", 30, 1, 3_600),                            // O8
];

/// KEY=VALUE lines of connector/.env (comments and blanks ignored).
fn dotenv() -> std::collections::HashMap<String, String> {
    let Ok(text) = std::fs::read_to_string(".env") else {
        return Default::default();
    };
    text.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|l| l.split_once('='))
        .map(|(k, v)| (k.trim().to_string(), v.trim().trim_matches('"').to_string()))
        .collect()
}

fn generate_authz_timing() {
    println!("cargo:rerun-if-changed=.env");
    let file = dotenv();
    let mut values = std::collections::HashMap::new();
    let mut out = String::from("// @generated by build.rs from the build environment / connector/.env.\n");
    for (key, default, min, max) in AUTHZ_TIMING {
        println!("cargo:rerun-if-env-changed={key}");
        let (raw, source) = match std::env::var(key) {
            Ok(v) => (v, "build environment"),
            Err(_) => match file.get(key) {
                Some(v) => (v.clone(), "connector/.env"),
                None => (default.to_string(), "default"),
            },
        };
        let value: u64 = raw
            .parse()
            .unwrap_or_else(|_| panic!("{key}={raw:?} (from {source}) is not a whole number"));
        if value < min || value > max {
            panic!("{key}={value} (from {source}) is outside {min}..={max}");
        }
        values.insert(key, value);
        out.push_str(&format!("pub const {key}: u64 = {value}; // {source}\n"));
    }
    if values["CONTROL_RECONNECT_BASE_MS"] > values["CONTROL_RECONNECT_MAX_MS"] {
        panic!("CONTROL_RECONNECT_BASE_MS must not exceed CONTROL_RECONNECT_MAX_MS");
    }
    out.push_str(&format!("pub const H_MS_AT_BUILD: u64 = {H_MS};\n"));
    let dest = std::path::Path::new(&std::env::var("OUT_DIR").unwrap()).join("authz_timing.rs");
    std::fs::write(dest, out).expect("write authz_timing.rs");
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    generate_authz_timing();

    // Tell cargo to re-run this build script only when the proto file changes.
    println!("cargo:rerun-if-changed=../proto/connector/v1/connector.proto");
    println!("cargo:rerun-if-changed=../proto/shield/v1/shield.proto");
    println!("cargo:rerun-if-changed=../proto/client/v1/client.proto");

    // Compile the protos into Rust gRPC stubs.
    // This generates both client and server code, but we only use the client side.
    tonic_prost_build::configure().compile_protos(
        &[
            "../proto/connector/v1/connector.proto",
            "../proto/shield/v1/shield.proto",
            "../proto/client/v1/client.proto",
        ],
        &[".."],
    )?;

    Ok(())
}
